SELECT ARRAY_LENGTH(arr) AS a, arr[OFFSET(0)] AS b, arr[SAFE_OFFSET(5)] AS c, arr[ORDINAL(1)] AS d, ARRAY_CONCAT(arr, [4]) AS e, ARRAY_TO_STRING(['a','b'], ',') AS f, ARRAY_REVERSE(arr) AS g, GENERATE_ARRAY(1, 3) AS h, ARRAY(SELECT x * 2 FROM UNNEST(arr) AS x) AS i, (SELECT SUM(x) FROM UNNEST(arr) AS x) AS j FROM (SELECT [1,2,3] AS arr)
